// Quizzone - base station (plug into the PC)
// Generated by firmware/tools/build.mjs - edit firmware/src instead.

// ===== qz_config.ts =====
// =============================================================================
//  Quizzone - shared settings. Must be IDENTICAL on every team device
//  and on the base station (the micro:bit plugged into the computer).
// =============================================================================

// --- Radio network ----------------------------------------------------------
// The micro:bit radio frequency is 2400 MHz + band (MHz). MakeCode's default
// band is 7 (2407 MHz), which sits on top of Wi-Fi channel 1: avoid it.
// Verified in the codal/pxt source: group 0..255, band 0..83, power 0..7.
// Pick a group/band that no other micro:bit activity in the venue uses.
const QZ_GROUP = 77;
const QZ_BAND = 25;
const QZ_TX_POWER = 7;

// Firmware / protocol version reported by team devices (uint8).
const QZ_FW = 1;

// Maximum number of teams (the ack/result masks are 16 bits wide).
const QZ_MAX_TEAMS = 16;

// --- Timing (milliseconds) --------------------------------------------------
const QZ_BEACON_MS = 100;        // base -> teams state beacon period
const QZ_SERVER_TIMEOUT_MS = 3000; // base: no valid state line from the PC -> OFFLINE
const QZ_BASE_HELLO_MS = 2000;   // base -> PC "H" heartbeat line period
const QZ_STALE_MS = 1500;        // team: ignore key presses if last beacon is older
const QZ_NOLINK_MS = 2500;       // team: show "no link" if no beacon for this long
const QZ_DEBOUNCE_MS = 10;       // key must be stable this long to count
const QZ_HB_MS = 1000;           // team: idle heartbeat (state) period, +0..300 jitter
const QZ_UNASSIGNED_HB_MS = 600; // team without a slot announces itself this often (+0..400)
const QZ_RXQ_MAX = 64;           // base: software queue between radio and serial

// ===== qz_protocol.ts =====
// =============================================================================
//  Quizzone - wire protocol (radio packets + serial lines).
//  Spec: protocol/PROTOCOL.md.  Pure functions only: no MakeCode API here, so
//  the same file runs in the Node test harness.
//  MakeCode static-TS rules followed: no enums, no namespaces, no modules.
// =============================================================================

const QZ_MAGIC = 0xC5;

const QZ_T_STATE = 1;    // team  -> base
const QZ_T_BEACON = 2;   // base  -> teams
const QZ_T_ASSIGN = 3;   // base  -> one team (by serial)
const QZ_T_IDENT = 4;    // base  -> one team (by serial)

const QZ_STATE_LEN = 13;
const QZ_BEACON_LEN = 16;
const QZ_ASSIGN_LEN = 7;
const QZ_IDENT_LEN = 7;

// Phases carried in beacons.
const QZ_PH_IDLE = 0;
const QZ_PH_OPEN = 1;
const QZ_PH_CLOSED = 2;
const QZ_PH_REVEAL = 3;
const QZ_PH_OFFLINE = 4;   // generated by the base when the PC went silent

const QZ_UNASSIGNED = 255;

// STATE.flags bits
const QZ_SF_LOCKED = 1;        // bit0: device holds an answer for state.q
const QZ_SF_ACKED = 2;         // bit1: device has seen the base acknowledge it
const QZ_SF_PHASE_SHIFT = 2;   // bits2-4: phase of the last beacon the device processed
const QZ_SF_TEST = 32;         // bit5: last beacon had test flag

// BEACON.flags bits
const QZ_BF_TEST = 1;          // bit0: stress-test mode (devices auto-answer)
const QZ_BF_NANS_SHIFT = 2;    // bits2-4: number of valid answers (3..5)

class QzMsg {
    type = 0;
    // STATE fields
    slot = 0;
    seq = 0;
    q = 0;
    ans = 0;
    elapsed = 0;
    flags = 0;
    fw = 0;
    presses = 0;
    bmiss = 0;
    // BEACON fields (q, elapsed, flags are shared with STATE)
    phase = 0;
    limit = 0;      // units of 100 ms
    ack = 0;
    correct = 0;
    wrong = 0;
    bseq = 0;
    // ASSIGN / IDENT
    target = 0;     // device serial number as int32
    arg = 0;        // slot (ASSIGN) or pattern (IDENT)
    constructor() { }
}

function qzClamp16(v: number): number {
    if (v < 0) return 0;
    if (v > 65535) return 65535;
    return v;
}

function qzEncState(m: QzMsg): number[] {
    const e = qzClamp16(m.elapsed);
    return [QZ_MAGIC, QZ_T_STATE, m.slot & 255, m.seq & 255, m.q & 255, m.ans & 255,
        e & 255, (e >> 8) & 255, m.flags & 255, m.fw & 255,
        m.presses & 255, (m.presses >> 8) & 255, m.bmiss & 255];
}

function qzEncBeacon(m: QzMsg): number[] {
    const e = qzClamp16(m.elapsed);
    const l = qzClamp16(m.limit);
    return [QZ_MAGIC, QZ_T_BEACON, m.phase & 255, m.q & 255,
        e & 255, (e >> 8) & 255, l & 255, (l >> 8) & 255,
        m.ack & 255, (m.ack >> 8) & 255,
        m.correct & 255, (m.correct >> 8) & 255,
        m.wrong & 255, (m.wrong >> 8) & 255,
        m.flags & 255, m.bseq & 255];
}

function qzEncTargeted(type: number, target: number, arg: number): number[] {
    return [QZ_MAGIC, type, target & 255, (target >> 8) & 255, (target >> 16) & 255,
        (target >> 24) & 255, arg & 255];
}

// Returns null for anything that is not a well-formed Quizzone packet.
function qzDecode(b: number[]): QzMsg {
    if (b == null || b.length < 2 || b[0] != QZ_MAGIC) return null;
    const m = new QzMsg();
    m.type = b[1];
    if (m.type == QZ_T_STATE) {
        if (b.length != QZ_STATE_LEN) return null;
        m.slot = b[2]; m.seq = b[3]; m.q = b[4]; m.ans = b[5];
        m.elapsed = b[6] | (b[7] << 8);
        m.flags = b[8]; m.fw = b[9];
        m.presses = b[10] | (b[11] << 8);
        m.bmiss = b[12];
        return m;
    }
    if (m.type == QZ_T_BEACON) {
        if (b.length != QZ_BEACON_LEN) return null;
        m.phase = b[2]; m.q = b[3];
        m.elapsed = b[4] | (b[5] << 8);
        m.limit = b[6] | (b[7] << 8);
        m.ack = b[8] | (b[9] << 8);
        m.correct = b[10] | (b[11] << 8);
        m.wrong = b[12] | (b[13] << 8);
        m.flags = b[14]; m.bseq = b[15];
        return m;
    }
    if (m.type == QZ_T_ASSIGN || m.type == QZ_T_IDENT) {
        if (b.length != QZ_ASSIGN_LEN) return null;
        m.target = b[2] | (b[3] << 8) | (b[4] << 16) | (b[5] << 24);
        m.arg = b[6];
        return m;
    }
    return null;
}

// ---------------------------------------------------------------------------
//  Serial lines:  "<payload>*<HH>"  where HH = XOR of all payload bytes, hex.
// ---------------------------------------------------------------------------

function qzChecksum(s: string): number {
    let c = 0;
    for (let i = 0; i < s.length; i++) c ^= s.charCodeAt(i);
    return c & 255;
}

function qzHexDigit(v: number): string {
    return "0123456789ABCDEF".charAt(v & 15);
}

function qzHex2(v: number): string {
    return qzHexDigit(v >> 4) + qzHexDigit(v);
}

// Unsigned 8-digit hex of an int32.
function qzHex8(v: number): string {
    let s = "";
    for (let i = 7; i >= 0; i--) s += qzHexDigit((v >> (i * 4)) & 15);
    return s;
}

function qzAddChecksum(payload: string): string {
    return payload + "*" + qzHex2(qzChecksum(payload));
}

// Returns the payload if the line is well-formed and the checksum matches,
// otherwise null. Trailing CR/LF/spaces are ignored.
function qzStripLine(line: string): string {
    let end = line.length;
    while (end > 0) {
        const c = line.charCodeAt(end - 1);
        if (c == 10 || c == 13 || c == 32) end--; else break;
    }
    if (end < 4) return null;
    if (line.charAt(end - 3) != "*") return null;
    const payload = line.substr(0, end - 3);
    const hh = qzParseHex(line.substr(end - 2, 2));
    if (hh < 0) return null;
    if (qzChecksum(payload) != hh) return null;
    return payload;
}

// Parses hex digits into an int32 (wraps like unsigned). Returns -1 on a bad char
// or empty string; callers that need all 32 bits must use qzParseHex32.
function qzParseHex(s: string): number {
    if (s.length == 0 || s.length > 7) return -1;
    let v = 0;
    for (let i = 0; i < s.length; i++) {
        const d = qzHexVal(s.charCodeAt(i));
        if (d < 0) return -1;
        v = (v << 4) | d;
    }
    return v;
}

function qzHexVal(c: number): number {
    if (c >= 48 && c <= 57) return c - 48;
    if (c >= 65 && c <= 70) return c - 55;
    if (c >= 97 && c <= 102) return c - 87;
    return -1;
}

// 8 hex digits -> int32. Sets ok[0] = false on error.
function qzParseHex32(s: string, ok: boolean[]): number {
    if (s.length != 8) { ok[0] = false; return 0; }
    let v = 0;
    for (let i = 0; i < 8; i++) {
        const d = qzHexVal(s.charCodeAt(i));
        if (d < 0) { ok[0] = false; return 0; }
        v = (v << 4) | d;
    }
    return v;
}

// Decimal integer with optional leading '-'. Sets ok[0] = false on error.
function qzParseInt(s: string, ok: boolean[]): number {
    if (s.length == 0 || s.length > 9) { ok[0] = false; return 0; }
    let i = 0;
    let neg = false;
    if (s.charAt(0) == "-") { neg = true; i = 1; if (s.length == 1) { ok[0] = false; return 0; } }
    let v = 0;
    for (; i < s.length; i++) {
        const c = s.charCodeAt(i);
        if (c < 48 || c > 57) { ok[0] = false; return 0; }
        v = v * 10 + (c - 48);
    }
    return neg ? -v : v;
}

// ===== qz_base.ts =====
// =============================================================================
//  Base station logic (the micro:bit plugged into the PC by USB).
//
//  Radio  -> PC : every valid team STATE packet becomes one "T ..." line.
//  PC -> radio  : the PC sends its full game state ("S ..." line) several times
//                 per second; the base re-broadcasts it as a BEACON every
//                 QZ_BEACON_MS, interpolating the elapsed time locally.
//                 "A"/"N" lines become ASSIGN/IDENT packets.
//
//  The radio receive path only enqueues (the hardware queue holds just 4
//  packets, so the handler must return immediately); lines are written to the
//  serial port from tick().
// =============================================================================

interface QzBaseHal {
    radioSend(bytes: number[]): void;
    serialWrite(text: string): void;   // may block while the UART drains
}

class QzRxItem {
    serial = 0;
    rssi = 0;
    at = 0;
    msg: QzMsg = null;
    constructor() { }
}

class QzBase {
    hal: QzBaseHal;

    // Latest state received from the PC
    sPhase = QZ_PH_IDLE;
    sQ = 0;
    sElapsed = 0;
    sLimit = 0;       // ms
    sAck = 0;
    sCorrect = 0;
    sWrong = 0;
    sFlags = 0;
    sAt = -1000000;
    sValid = false;

    bseq = 0;
    nextBeacon = 0;
    nextHello = 0;
    rxq: QzRxItem[] = [];

    // Counters reported in the "H" line
    cOverflow = 0;    // software queue overflow (dropped oldest)
    cForeign = 0;     // radio packets that are not valid Quizzone packets
    cBadLine = 0;     // serial lines with bad checksum / unparsable
    cRxOk = 0;        // valid team packets received

    constructor(hal: QzBaseHal, now: number) {
        this.hal = hal;
        this.nextBeacon = now;
        this.nextHello = now;
    }

    // ---- radio in ---------------------------------------------------------
    onRadio(bytes: number[], serial: number, rssi: number, now: number) {
        const m = qzDecode(bytes);
        if (m == null) { this.cForeign++; return; }
        if (m.type != QZ_T_STATE) return;   // our own beacons etc. are not interesting
        if (this.rxq.length >= QZ_RXQ_MAX) {
            this.rxq.shift();
            this.cOverflow++;
        }
        const it = new QzRxItem();
        it.serial = serial;
        it.rssi = rssi;
        it.at = now;
        it.msg = m;
        this.rxq.push(it);
        this.cRxOk++;
    }

    // ---- serial in --------------------------------------------------------
    onSerialLine(line: string, now: number) {
        const p = qzStripLine(line);
        if (p == null) { if (line.length > 0) this.cBadLine++; return; }
        const f = p.split(" ");
        const cmd = f[0];
        const ok = [true];
        if (cmd == "S" && f.length == 9) {
            const phase = qzParseInt(f[1], ok);
            const q = qzParseInt(f[2], ok);
            const elapsed = qzParseInt(f[3], ok);
            const limit = qzParseInt(f[4], ok);
            const ack = qzParseInt(f[5], ok);
            const correct = qzParseInt(f[6], ok);
            const wrong = qzParseInt(f[7], ok);
            const flags = qzParseInt(f[8], ok);
            if (!ok[0] || phase < 0 || phase > 3) { this.cBadLine++; return; }
            this.sPhase = phase; this.sQ = q & 255; this.sElapsed = qzClamp16(elapsed);
            this.sLimit = limit < 0 ? 0 : limit;
            this.sAck = ack & 0xFFFF; this.sCorrect = correct & 0xFFFF; this.sWrong = wrong & 0xFFFF;
            this.sFlags = flags & 255;
            this.sAt = now;
            this.sValid = true;
        } else if ((cmd == "A" || cmd == "N") && f.length == 3) {
            const serial = qzParseHex32(f[1], ok);
            const arg = qzParseInt(f[2], ok);
            if (!ok[0] || arg < 0 || arg > 255) { this.cBadLine++; return; }
            this.hal.radioSend(qzEncTargeted(cmd == "A" ? QZ_T_ASSIGN : QZ_T_IDENT, serial, arg));
        } else if (cmd == "P" && f.length == 1) {
            this.nextHello = now;   // answer with an H line on the next tick
        } else {
            this.cBadLine++;
        }
    }

    serverAlive(now: number): boolean {
        return this.sValid && (now - this.sAt) < QZ_SERVER_TIMEOUT_MS;
    }

    // ---- periodic ---------------------------------------------------------
    tick(now: number) {
        if (now >= this.nextBeacon) {
            this.nextBeacon = now + QZ_BEACON_MS;
            this.sendBeacon(now);
        }
        if (this.rxq.length > 0) {
            this.writeTeamLine(this.rxq.shift());
        } else if (now >= this.nextHello) {
            this.nextHello = now + QZ_BASE_HELLO_MS;
            this.hal.serialWrite(qzAddChecksum("H " + QZ_FW + " " + QZ_GROUP + " " + QZ_BAND + " " +
                Math.idiv(now, 1000) + " " + this.cOverflow + " " + this.cForeign + " " +
                this.cBadLine + " " + this.cRxOk) + "\n");
        }
    }

    sendBeacon(now: number) {
        const m = new QzMsg();
        if (this.serverAlive(now)) {
            m.phase = this.sPhase;
            m.q = this.sQ;
            m.elapsed = this.sPhase == QZ_PH_OPEN ? qzClamp16(this.sElapsed + (now - this.sAt)) : this.sElapsed;
            m.limit = Math.idiv(this.sLimit + 99, 100);
            m.ack = this.sAck;
            m.correct = this.sCorrect;
            m.wrong = this.sWrong;
            m.flags = this.sFlags;
        } else {
            m.phase = QZ_PH_OFFLINE;
        }
        m.bseq = this.bseq;
        this.bseq = (this.bseq + 1) & 255;
        this.hal.radioSend(qzEncBeacon(m));
    }

    writeTeamLine(it: QzRxItem) {
        const m = it.msg;
        this.hal.serialWrite(qzAddChecksum("T " + qzHex8(it.serial) + " " + it.rssi + " " + m.slot + " " +
            m.seq + " " + m.q + " " + m.ans + " " + m.elapsed + " " + m.flags + " " + m.fw + " " +
            m.presses + " " + m.bmiss + " " + (it.at & 0x7FFFFFFF)) + "\n");
    }
}

// ===== base_main.ts =====
// =============================================================================
//  BASE STATION - MakeCode glue (micro:bit plugged into the PC by USB).
//  Logic lives in qz_base.ts.
// =============================================================================

class BaseHal implements QzBaseHal {
    radioSend(bytes: number[]): void {
        const b = control.createBuffer(bytes.length);
        for (let i = 0; i < bytes.length; i++) b[i] = bytes[i];
        radio.sendBuffer(b);
    }
    serialWrite(text: string): void {
        // writeString, not writeLine: writeLine pads every line to 32 characters.
        serial.writeString(text);
    }
}

radio.setGroup(QZ_GROUP);
radio.setFrequencyBand(QZ_BAND);
radio.setTransmitPower(QZ_TX_POWER);
radio.setTransmitSerialNumber(false);

serial.redirectToUSB();
serial.setRxBufferSize(128);

const qzBase = new QzBase(new BaseHal(), control.millis());

// Radio handler: must be fast (hardware queue holds only 4 packets). It only enqueues.
radio.onReceivedBuffer(function (b: Buffer) {
    const arr: number[] = [];
    for (let i = 0; i < b.length; i++) arr.push(b[i]);
    qzBase.onRadio(arr,
        radio.receivedPacket(RadioPacketProperty.SerialNumber),
        radio.receivedPacket(RadioPacketProperty.SignalStrength),
        control.millis());
});

serial.onDataReceived(serial.delimiters(Delimiters.NewLine), function () {
    qzBase.onSerialLine(serial.readUntil(serial.delimiters(Delimiters.NewLine)), control.millis());
});

basic.showString("Q");

control.inBackground(function () {
    let blink = false;
    let lastBlink = 0;
    while (true) {
        const now = control.millis();
        qzBase.tick(now);
        if (now - lastBlink >= 500) {
            lastBlink = now;
            blink = !blink;
            // usually Q, with added blinking ! if server not alive
            if (qzBase.serverAlive(now)) { 
                basic.showString("Q");
            } else {
                if (blink){
                    basic.showString("Q");
                } else {
                    basic.showLeds(`
. # # . #
# . . # #
# . . # #
. # # . .
. . # # #
`); 
                }
            }
        }
        basic.pause(1);
    }
});
